// works with no internet. Every rule it follows is in src/ai-rules.js; this module applies the rules before the
// model (risk words, what it gets) and after it (the check of every answer), and asks the model in between.
// Nothing written to it is stored or sent: the conversation lives in memory and is forgotten when the panel closes.
import { AI_MODEL, publicBase } from './ai-model.js';
import { beforeModel, checkAnswer, countHeld, notSentText, safeText, selfReported, systemPrompt } from './ai-rules.js';

const here = (path) => new URL(`../${path}`, import.meta.url).href;
const ENGINE = here('vendor/web-llm/web-llm.js');
// The same files are pinned for both places the model can come from (Subresource Integrity, checked by WebLLM).
const INTEGRITY = Object.freeze({
  config: 'sha256-faSVQhLT8hqRzD5pPRefYyE/1XNWeWhH9l1/lUeKH54=',
  model_lib: 'sha256-FV73NZyFn31kb0xa3FSNd5R12j4xlnAcep1LgoJ1Wag=',
  tokenizer: { 'tokenizer.json': 'sha256-wDghF+oynN8JcEETL21zWSS2l5JNb2/DlFcT6WzodTk=' },
  onFailure: 'error',
});
// Answer lengths and sampling: engineering settings, not rules.
export const GENERATION = Object.freeze({ analyse: { max_tokens: 300, temperature: 0.3, top_p: 0.9 }, session: { max_tokens: 260, temperature: 0.5, top_p: 0.9 } });

const st = { phase: 'idle', engine: null, source: null, error: null, loading: null, lastSpeed: null, listeners: new Set() };
export const aiState = () => ({ phase: st.phase, source: st.source, error: st.error, lastSpeed: st.lastSpeed });

// ---------- the mode, for the status line (space rule E, "mode-visible" in src/ai-rules.js) ----------
// NASA-STD-3001 Vol 2 [V2 10161] (the automation's state and mode) and [V2 10162] (notice of a mode change).
// 'off' (the Settings switch), 'loading', 'rules-only' (this browser cannot run it, or it failed or stopped),
// 'ready', or 'idle' (on; it starts when an AI panel asks). Listeners hear every change (src/crew.js redraws).
const modeListeners = new Set();
export const onAiMode = (fn) => { modeListeners.add(fn); return () => modeListeners.delete(fn); };
function modeChanged() { for (const f of modeListeners) { try { f(); } catch { /* the listener's own error */ } } }
export function aiMode(on = true) {
  if (!on) return 'off';
  if (st.phase === 'loading') return 'loading';
  if (st.phase === 'failed' || (support && !support.ok)) return 'rules-only';
  if (st.phase === 'ready') return 'ready';
  return 'idle';
}
// The one plain notice at a change of mode, or null when there is nothing to say.
export function modeNotice(from, to) {
  if (!from || from === to) return null;
  if (to === 'off') return 'The AI is off. Everything else works: the automation decides the levels.';
  if (to === 'loading') return 'The AI is starting on this computer. Everything else works.';
  if (to === 'ready') return 'The AI is ready.';
  if (to === 'rules-only') {
    if (from === 'loading') return 'The AI could not start: rules only now. Everything else works.';
    if (from === 'ready') return 'The AI stopped: rules only now. Everything else works.';
    return 'This browser cannot run the AI: rules only now. Everything else works.';
  }
  if (to === 'idle' && from === 'off') return 'The AI is on. It starts when you open an AI panel.';
  return null;
}

// ---------- can this browser run it? ----------
let support = null;
export async function aiSupport(nav = globalThis.navigator) {
  if (support) return support;
  const no = (why, code) => { support = { ok: false, why, code }; modeChanged(); return support; };
  if (!globalThis.isSecureContext) return no('This page is not opened from a secure address (https or this computer), so the browser does not allow WebGPU.', 'insecure');
  if (!nav || !nav.gpu) return no('This browser has no WebGPU, which the AI needs. Chrome or Edge on a computer have it.', 'no-webgpu');
  let adapter = null;
  try { adapter = await nav.gpu.requestAdapter({ powerPreference: 'high-performance' }); } catch { adapter = null; }
  if (!adapter) return no('This browser has WebGPU, but no graphics chip is available to it (it may be turned off).', 'no-adapter');
  const missing = AI_MODEL.requiredFeatures.filter((f) => !adapter.features.has(f));
  if (missing.length) return no(`This graphics chip lacks a feature the model needs (${missing.join(', ')}).`, 'feature');
  // navigator.deviceMemory is rounded and capped at 8 GB where it exists; under 4 GB the model would not fit beside the page.
  if (typeof nav.deviceMemory === 'number' && nav.deviceMemory < 4) return no(`This computer reports ${nav.deviceMemory} GB of memory; the model needs more.`, 'memory');
  return (support = { ok: true });
}
export const resetSupport = () => { support = null; };

// ---------- where the model comes from ----------
// An on-board install has the files in the program's own folder; the public demo downloads them once.
export async function modelSource(fetchFn = globalThis.fetch) {
  if (st.source) return st.source;
  const local = here(AI_MODEL.localDir);
  const onBoard = { kind: 'local', url: local, where: 'this program\'s own folder on this computer (no internet needed)' };
  const publicHost = { kind: 'public', url: publicBase(), where: 'Hugging Face (huggingface.co), the public model host' };
  // A model already in this browser's storage starts from there, whichever place filled it, with no request at all.
  if (await isStored(onBoard)) return (st.source = onBoard);
  if (await isStored(publicHost)) return (st.source = publicHost);
  // The program's own folder exists only where its own server runs (http or this computer). A static public copy
  // (GitHub Pages, https) has no such folder, so it is not asked there: the probe would only log a 404.
  const ownServer = typeof location === 'undefined' || location.protocol === 'http:' || location.hostname === 'localhost' || location.hostname === '127.0.0.1';
  if (ownServer) {
    try {
      const r = await fetchFn(`${local}mlc-chat-config.json`, { method: 'HEAD', cache: 'no-store' });
      if (r.ok) return (st.source = onBoard);
    } catch { /* not there */ }
  }
  return (st.source = publicHost);
}

// Is the model already in this browser's storage (downloaded after an earlier yes)?
export async function isStored(source) {
  try {
    if (!globalThis.caches) return false;
    const keys = (await (await caches.open('webllm/model')).keys()).map((r) => r.url);
    const shards = keys.filter((k) => k.startsWith(`${source.url}params_shard_`)).length;
    return keys.includes(`${source.url}tensor-cache.json`) && shards >= AI_MODEL.shards;
  } catch { return false; }
}

// ---------- start, stop ----------
const phaseOf = (text) => (/fetch/i.test(text) ? 'download' : /cache/i.test(text) ? 'cache' : /shader|gpu|compil/i.test(text) ? 'gpu' : 'start');
// onProgress({ part: 0..1, phase: 'download' | 'cache' | 'gpu' | 'start' })
// A panel opened again while the model loads gets the same progress.
export function startAi({ onProgress = () => {} } = {}) {
  if (st.engine) return Promise.resolve(st.engine);
  st.listeners.add(onProgress);
  if (st.loading) return st.loading;
  st.phase = 'loading';
  st.error = null;
  st.off = false;
  modeChanged();
  st.loading = (async () => {
    const source = await modelSource();
    const webllm = await import(ENGINE);
    const appConfig = {
      model_list: [{
        model: source.url, model_id: AI_MODEL.id, model_lib: here(AI_MODEL.lib),
        required_features: AI_MODEL.requiredFeatures, overrides: { context_window_size: AI_MODEL.contextTokens },
        integrity: INTEGRITY,
      }],
      cacheBackend: 'cache',
    };
    const engine = await webllm.CreateMLCEngine(AI_MODEL.id, {
      appConfig, logLevel: 'WARN',
      initProgressCallback: (r) => { for (const f of st.listeners) f({ part: Number(r.progress) || 0, phase: phaseOf(String(r.text || '')) }); },
    });
    // Turned off while it loaded: free the graphics memory at once.
    if (st.off) { try { await engine.unload(); } catch { /* gone */ } throw new Error('The AI was turned off.'); }
    st.engine = engine;
    st.phase = 'ready';
    modeChanged();
    return engine;
  })().catch((e) => {
    st.phase = st.off ? 'idle' : 'failed';
    st.error = st.off ? 'The AI is off.' : plainError(e);
    st.engine = null;
    modeChanged();
    throw new Error(st.error);
  }).finally(() => { st.loading = null; st.listeners.clear(); });
  return st.loading;
}

export function plainError(e) {
  const m = String((e && e.message) || e || '');
  if (/integrity/i.test(m)) return 'A model file did not match its fixed fingerprint, so it was not used.';
  if (/Failed to fetch|NetworkError|network|Cannot fetch|404|ERR_/i.test(m)) return 'The model files could not be loaded: no internet, the model host did not answer, or the files are not in the program\'s folder. On board, put them there with node tools/fetch-model.mjs.';
  if (/quota|QuotaExceeded|storage/i.test(m)) return 'This browser has no room left to store the model (about 0.9 GB).';
  if (/memory|OutOfMemory|allocation|device.*lost|lost.*device|disposed|not loaded/i.test(m)) return 'The graphics chip let the model go, often for lack of memory. On a computer with two graphics chips, set the browser to the high-performance one (Windows Settings, Display, Graphics), close other programs, then start the AI again.';
  if (/feature|f16/i.test(m)) return 'This graphics chip lacks a feature the model needs (shader-f16).';
  if (/WebGPU|adapter|gpu/i.test(m)) return 'WebGPU could not start on this computer.';
  return 'The AI could not start on this computer.';
}

// The graphics chip let the model go while it answered (seen on this laptop's integrated chip: "Object has already
// been disposed", then "Model not loaded"): drop the engine, so the panels say so once and offer to start again.
export const isLost = (e) => /disposed|not loaded|device.*lost|lost.*device|OutOfMemory|out of memory/i.test(String((e && e.message) || e || ''));
async function lose(e) {
  const engine = st.engine;
  st.engine = null;
  st.phase = 'failed';
  st.error = plainError(e);
  modeChanged();
  if (engine) { try { await engine.unload(); } catch { /* already gone */ } }
  return new Error(st.error);
}

// The "AI is working" switch off: free the graphics memory. The model stays stored for next time.
export async function stopAi() {
  const e = st.engine;
  st.off = true;
  st.engine = null;
  st.phase = 'idle';
  modeChanged();
  if (e) { try { await e.unload(); } catch { /* already gone */ } }
}
// Forget the talk: the engine keeps nothing of it after this.
export async function forgetTalk() {
  const e = st.engine;
  if (e) { try { e.interruptGenerate(); await e.resetChat(); } catch { /* nothing to forget */ } }
}
export function interrupt() { if (st.engine) { try { st.engine.interruptGenerate(); } catch { /* idle */ } } }

// ---------- the check while the answer comes in ----------
// Only whole sentences are shown, and each time only after the whole text so far passed the check (layer 3), so
// nothing unchecked is ever on screen. A held answer is replaced by the fixed safe text; the count goes up by one
// and the text is dropped.
const lastBoundary = (t) => { let end = 0; for (const m of t.matchAll(/[.!?:]["')\]]?(?=\s)|\n/g)) end = m.index + m[0].length; return end; };
export async function guardedAnswer(pieces, { ctx = {}, place = 'analyse', onText = () => {}, stop = () => {}, count = countHeld } = {}) {
  let full = '';
  let shown = 0;
  const held = (rule) => { stop(); count(rule); const text = safeText(rule, place); onText(text, { held: rule, done: true }); return { text, held: rule }; };
  for await (const piece of pieces) {
    full += piece;
    const cut = lastBoundary(full);
    if (cut > shown) {
      const res = checkAnswer(full, ctx);
      if (!res.ok) return held(res.rule);
      shown = cut;
      onText(full.slice(0, cut).trim(), { held: null, done: false });
    }
  }
  const res = checkAnswer(full, ctx);
  if (!res.ok) return held(res.rule);
  const text = full.trim() || 'The AI gave no answer. Try again, or talk to a crewmate.';
  onText(text, { held: null, done: true });
  return { text, held: null };
}

// ---------- ask ----------
// kind: 'analyse' or 'session'. history: [{ role: 'user' | 'assistant', content }], the last one the person's.
// ctx: { level, red, data } (data only for 'analyse': the lines the panel shows). Returns
// { text, held: rule id or null, risk: true when Help now must open instead, speed: tokens per second }.
export async function askAi({ kind, history, ctx = {}, onText = () => {}, engine = st.engine }) {
  const last = history[history.length - 1];
  const pre = beforeModel(last ? last.content : '');
  // A message in another script: not given to the model (the word list could not read it), said on screen.
  if (!pre.ok && pre.rule === 'english-only') return { text: notSentText(kind === 'session' ? 'session' : 'analyse'), held: 'english-only', risk: false, speed: null };
  if (!pre.ok) return { text: null, held: null, risk: true };
  if (!engine) throw new Error('The AI is not started.');
  // Messages that opened Help now never reach the model, also later in the talk.
  const msgs = history.filter((m) => m.role !== 'user' || beforeModel(m.content).ok).map((m) => ({ role: m.role, content: String(m.content) }));
  // A reading the person typed ("my heart rate is 180") has not been checked by the automation: the answer check
  // then also holds playing it down or putting action off, as at a red level.
  const checkCtx = msgs.some((m) => m.role === 'user' && selfReported(m.content)) ? { ...ctx, selfReported: true } : ctx;
  const usage = { speed: null, finish: null };
  async function* pieces() {
    const stream = await engine.chat.completions.create({
      messages: [{ role: 'system', content: systemPrompt(kind, ctx) }, ...msgs],
      stream: true, stream_options: { include_usage: true }, ...GENERATION[kind === 'session' ? 'session' : 'analyse'],
    });
    for await (const chunk of stream) {
      const c = chunk.choices && chunk.choices[0];
      if (c && c.delta && c.delta.content) yield c.delta.content;
      if (c && c.finish_reason) usage.finish = c.finish_reason;
      if (chunk.usage && chunk.usage.extra) usage.speed = chunk.usage.extra.decode_tokens_per_s || null;
    }
  }
  let out;
  try {
    out = await guardedAnswer(pieces(), { ctx: checkCtx, place: kind === 'session' ? 'session' : 'analyse', onText, stop: () => { try { engine.interruptGenerate(); } catch { /* done */ } } });
  } catch (e) {
    if (isLost(e) && engine === st.engine) throw await lose(e);
    throw new Error(plainError(e));
  }
  if (usage.speed) st.lastSpeed = usage.speed;
  // An answer that reached the length limit says so, instead of stopping mid-sentence without a word.
  if (!out.held && usage.finish === 'length') {
    out.text = `${out.text} (The answer was cut short here.)`;
    onText(out.text, { held: null, done: true });
  }
  return { ...out, risk: false, speed: usage.speed };
}
